// Update small visual accents tracking dots markers pulseDot.className = "flex h-2.5 w-2.5 rounded-full animate-pulse " + clusterConfig.btnClass.split(" ")[1]; counterBadge.className = "text-xs font-bold uppercase tracking-wider bg-slate-950/60 px-3 py-1 rounded-full " + clusterConfig.badgeClass.split(" ").slice(1,3).join(" "); footerWt.className = "transition-colors duration-500 " + clusterConfig.footerColor;
// Restructure custom input metadata fields tracking context lblSubject.innerHTML = modeConfig.name.split(" ").slice(1).join(" ") + " Target Subject Concept <span class='text-rose-500'>*</span>"; inputSubject.placeholder = "Enter high resolution concept for " + modeConfig.name.split(" ").slice(1).join(" ") + "...";
