// Re-trigger visual placeholder states dynamically triggerMultiverseEmptyFeedState(modeConfig.emoji, modeConfig.name + " System Online", "Awaiting quantum subject inputs deployment metrics mapping vectors framework sequence."); counter = 0; updateLogsTrackingPanelDisplay(); }
function injectDynamicAspectRatios(ratioArray) { const selectRatio = document.getElementById('aspectRatio'); selectRatio.innerHTML = ''; ratioArray.forEach(function(ratioItem) { let elementOption = document.createElement('option'); elementOption.value = ratioItem.val; elementOption.innerText = ratioItem.text; selectRatio.appendChild(elementOption); }); }
// SWITCH TAB SYSTEM INSIDE GENERATED LOG CARDS window.switchPromptCardTab = function(tabInstance, logId, targetType) { const parentCard = document.getElementById('promptCard_' + logId); const allTabs = parentCard.querySelectorAll('.tab-trigger'); const textBlock = document.getElementById('text_' + logId); const jsonBlock = document.getElementById('json_' + logId); const btnCopy = parentCard.querySelector('.btn-copy-action');
allTabs.forEach(tab => { tab.classList.remove('text-white', 'border-b-2', 'border-cyan-500'); tab.classList.add('text-slate-500'); }); tabInstance.classList.add('text-white', 'border-b-2', 'border-cyan-500'); tabInstance.classList.remove('text-slate-500');
if (targetType === 'string') { textBlock.classList.remove('hidden'); jsonBlock.classList.add('hidden'); btnCopy.setAttribute('onclick', `copyEnginePromptStringPayload(this, ${logId}, 'string')`); btnCopy.innerText = "📋 Copy Manifest String Data"; } else { textBlock.classList.add('hidden'); jsonBlock.classList.remove('hidden'); btnCopy.setAttribute('onclick', `copyEnginePromptStringPayload(this, ${logId}, 'json')`); btnCopy.innerText = "⚡ Copy JSON Prompt"; } }
function triggerMultiverseEmptyFeedState(emoji, title, narrative) { const logContainer = document.getElementById('promptLogContainer'); logContainer.innerHTML = "\ <div class='h-full flex flex-col items-center justify-center text-center p-8' id='emptyState'>\ <div class='h-16 w-16 bg-slate-950 border border-slate-900 rounded-2xl flex items-center justify-center text-2xl shadow-inner mb-4 opacity-80 animate-bounce' id='emptyStateEmoji'>" + emoji + "</div>\ <h3 class='text-xs font-black text-slate-400 uppercase tracking-widest' id='emptyStateTitle'>" + title + "</h3>\ <p class='text-xs text-slate-500 mt-2 max-w-xs leading-relaxed font-medium' id='emptyStateDesc'>" + narrative + "</p>\ </div>\ "; }
// MAIN HIGH INTENSITY PROMPT STRUCTURING ENGINE LOGIC COMPILER RUNTIME function generatePrompt(activateChaosRandomizer) { let subjectValue = document.getElementById('subject').value.trim(); const imageRefUrl = document.getElementById('imgUrl').value.trim(); const customNegativeParam = document.getElementById('negativePrompt').value.trim(); const selectedAspectRatioSpec = document.getElementById('aspectRatio').value;
const targetModeObj = OMNI_ENGINE_MODES.find(m => m.id === currentMode); if (!targetModeObj) return;
const baseClusterObj = MULTIVERSE_CLUSTERS[targetModeObj.cluster] || MULTIVERSE_CLUSTERS['realism'];
if (activateChaosRandomizer) { subjectValue = drawRandomAsset(VOCABULARY_CORPUS.subjects); document.getElementById('subject').value = subjectValue; } else if (!subjectValue) { alert("Attention: Please insert a distinct operational objective core target conceptual layout text input subject descriptor parameter first!"); return; }
// Draw secondary matrix structural variables data randomly const randomizedStyle = drawRandomAsset(VOCABULARY_CORPUS.styles); const randomizedAdjective = drawRandomAsset(VOCABULARY_CORPUS.adjectives); const randomizedVibe = drawRandomAsset(VOCABULARY_CORPUS.vibes); const randomizedColorGrade = drawRandomAsset(VOCABULARY_CORPUS.colors); const secondaryBoosterPack = drawRandomAsset(baseClusterObj.boosters);
// 1. Build Standard Text String Output let engineeredPromptResultString = ""; if (imageRefUrl) engineeredPromptResultString += imageRefUrl + " "; engineeredPromptResultString += targetModeObj.phrase + " " + subjectValue + ", " + randomizedStyle + ", " + randomizedAdjective + ", " + randomizedVibe + ", " + randomizedColorGrade + ", " + secondaryBoosterPack + " " + selectedAspectRatioSpec; if (customNegativeParam) engineeredPromptResultString += " " + customNegativeParam;
// 2. Build Structured JSON Object Output (X-Style Architecture) const jsonOutputPayload = { meta: { engine_version: "OmniStudio Multiverse AI v1.1", core_universe: targetModeObj.name.split(" ").slice(1).join(" "), timestamp: new Date().toISOString() }, prompt: { image_reference: imageRefUrl || null, prefix_phrase: targetModeObj.phrase, core_concept: subjectValue, style_modifiers: [randomizedStyle, randomizedAdjective], vibe_ambience: randomizedVibe, color_grading: randomizedColorGrade, rendering_boosters: secondaryBoosterPack.split(", ").map(s => s.trim()), parameters: { aspect_ratio: selectedAspectRatioSpec.replace('--ar ', ''), negative_exclusion: customNegativeParam || null } }, compiled_raw: engineeredPromptResultString };
const formattedJsonString = JSON.stringify(jsonOutputPayload, null, 2);
// Evaporate empty state asset blocks if exists const currentEmptyStateContainerElement = document.getElementById('emptyState'); if (currentEmptyStateContainerElement) currentEmptyStateContainerElement.remove();
counter++; const feedContainerElement = document.getElementById('promptLogContainer');
let rowBadgeStyles, rowBorderHoverAccent, executionCopyBtnStyles, unifiedCopyText, elementLogsSerialBadgeLabel; rowBadgeStyles = baseClusterObj.badgeClass; rowBorderHoverAccent = "hover:border-" + baseClusterObj.footerColor.split("-")[1] + "-500/40"; executionCopyBtnStyles = "hover:bg-" + baseClusterObj.footerColor.split("-")[1] + "-500/20 hover:text-white"; elementLogsSerialBadgeLabel = targetModeObj.id.toUpperCase() + " LOG #" + counter; unifiedCopyText = "📋 Copy Manifest String Data";
let structuralImageLinkAttachmentBadgeElement = imageRefUrl ? "<span class='bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 text-[9px] font-black px-2.5 py-1 rounded-md tracking-wider uppercase flex items-center gap-1'>🔗 ASSET ATTACHED</span>" : "";
const rawRowLogCardTemplateHtmlMarkup = "\ <div class='bg-slate-900/40 p-5 rounded-2xl border border-slate-900 shadow-md flex flex-col justify-between gap-4 transition-all duration-300 group " + rowBorderHoverAccent + "' id='promptCard_" + counter + "'>\ <div class='flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 border-b border-slate-900/80 pb-3'>\ <div class='flex items-center gap-2 shrink-0'>\ <span class='text-[9px] font-black px-2.5 py-1 rounded-md tracking-wider uppercase " + rowBadgeStyles + "'>\ " + elementLogsSerialBadgeLabel + "\ </span>\ " + structuralImageLinkAttachmentBadgeElement + "\ </div>\ <!-- Dual Tab Switcher -->\ <div class='flex items-center gap-4 text-xs font-bold bg-slate-950 px-3 py-1.5 rounded-xl border border-slate-900/60'>\ <button class='tab-trigger text-white border-b-2 border-cyan-500 pb-0.5 cursor-pointer transition' onclick='switchPromptCardTab(this, " + counter + ", \"string\")'>📝 Raw Text</button>\ <button class='tab-trigger text-slate-500 pb-0.5 cursor-pointer transition' onclick='switchPromptCardTab(this, " + counter + ", \"json\")'>⚡ JSON Prompt</button>\ </div>\ <button class='btn-copy-action text-xs bg-slate-950 border border-slate-800 text-slate-300 font-extrabold py-1.5 px-4 rounded-xl transition duration-200 cursor-pointer shadow-sm sm:group-hover:scale-105 " + executionCopyBtnStyles + "' onclick='copyEnginePromptStringPayload(this, " + counter + ", \"string\")'>\ " + unifiedCopyText + "\ </button>\ </div>\ <!-- Output Blocks -->\ <p class='text-sm font-medium text-slate-300 leading-relaxed break-words select-all font-mono tracking-tight bg-slate-950/80 p-4 rounded-xl border border-slate-950 shadow-inner' id='text_" + counter + "'>" + engineeredPromptResultString + "</p>\ <pre class='hidden text-xs font-mono text-emerald-400 overflow-x-auto custom-scroll bg-slate-950/90 p-4 rounded-xl border border-slate-950 shadow-inner select-all whitespace-pre' id='json_" + counter + "'>" + formattedJsonString + "</pre>\ </div>\ ";
feedContainerElement.insertAdjacentHTML('afterbegin', rawRowLogCardTemplateHtmlMarkup); updateLogsTrackingPanelDisplay(); }
function copyEnginePromptStringPayload(targetButtonDomElement, uniqueLogCardId, currentActiveType) { const elementTargetId = currentActiveType === 'string' ? "text_" + uniqueLogCardId : "json_" + uniqueLogCardId; const targetedTextStringSourcePayload = document.getElementById(elementTargetId).innerText;
navigator.clipboard.writeText(targetedTextStringSourcePayload).then(function() { const defaultLabel = currentActiveType === 'string' ? "📋 Copy Manifest String Data" : "⚡ Copy JSON Prompt"; targetButtonDomElement.innerText = "✨ Copied Successfully!"; targetButtonDomElement.style.borderColor = "transparent"; targetButtonDomElement.style.backgroundColor = "rgba(16, 185, 129, 0.2)"; targetButtonDomElement.style.color = "#34d399";
setTimeout(function() { targetButtonDomElement.innerText = defaultLabel; targetButtonDomElement.style.borderColor = ""; targetButtonDomElement.style.backgroundColor = ""; targetButtonDomElement.style.color = ""; }, 1200); }).catch(function(errorSystemLog) { console.error('Critical Framework Error: Clipboard write process failed.', errorSystemLog); }); }
function updateLogsTrackingPanelDisplay() { document.getElementById('promptCounter').innerText = counter + " Quantum Logs Transmitted"; }
// INTERACTIVE MODAL OVERLAY ROUTINE LOGIC function toggleSourceModal(shouldShowModal) { const modalOverlay = document.getElementById('sourceModal'); const modalInnerBox = document.getElementById('modalBox');
if (shouldShowModal) { document.getElementById('themeSourceArea').value = document.documentElement.outerHTML; modalOverlay.classList.remove('hidden'); setTimeout(function() { modalOverlay.classList.remove('opacity-0'); modalInnerBox.classList.remove('scale-95'); }, 30); } else { modalOverlay.classList.add('opacity-0'); modalInnerBox.classList.add('scale-95'); setTimeout(function() { modalOverlay.classList.add('hidden'); }, 300); } }
function copyWholeThemeSourcePayload(buttonInstance) { const themeSourceTextPayload = document.getElementById('themeSourceArea').value; navigator.clipboard.writeText(themeSourceTextPayload).then(function() { const previousButtonLabelText = "📋 Copy Entire Theme Code"; buttonInstance.innerText = "⚡ XML Code Copied Successfully!"; buttonInstance.style.backgroundImage = "none"; buttonInstance.style.backgroundColor = "#10b981";
setTimeout(function() { buttonInstance.innerText = previousButtonLabelText; buttonInstance.style.backgroundImage = ""; buttonInstance.style.backgroundColor = ""; }, 1500); }).catch(function(err) { console.error('Failed to copy code: ', err); }); }
function resetDashboard() { if (confirm('Are you absolutely certain you want to initiate a full operational core cycle flush sequence?')) { document.getElementById('subject').value = ''; document.getElementById('imgUrl').value = ''; document.getElementById('negativePrompt').value = ''; counter = 0; switchEngineMode(); } }
function toggleZenMode(activateZenLayoutState) { const leftSidebarMenuPanelContainer = document.getElementById('leftMenuPanel'); const triggersBtnZenModeActivation = document.getElementById('btnZenMode'); const triggersBtnDefaultViewRestore = document.getElementById('btnDefaultView');
if (activateZenLayoutState) { leftSidebarMenuPanelContainer.classList.add('hidden'); triggersBtnZenModeActivation.classList.add('hidden'); triggersBtnDefaultViewRestore.classList.remove('hidden'); } else { leftSidebarMenuPanelContainer.classList.remove('hidden'); triggersBtnZenModeActivation.classList.remove('hidden'); triggersBtnDefaultViewRestore.classList.add('hidden'); } }
